"use client";

import Link from "next/link";
import { FormEvent, useState } from "react";
import { useParams } from "next/navigation";
import {
  ApiError,
  requestConsent,
  withdrawConsent,
  type ConsentRequestOut,
  type ConsentWithdrawOut,
} from "@/lib/api";
import {
  ApiErrorAlert,
  FieldMessage,
  fieldErrorMap,
} from "@/components/forms/ApiErrorAlert";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

type ScopeState = {
  participation: boolean;
  public: boolean;
};

export default function CompetitorConsentPage() {
  const params = useParams<{ competitorId: string }>();
  const competitorId = params.competitorId;

  const [guardianName, setGuardianName] = useState("");
  const [guardianEmail, setGuardianEmail] = useState("");
  const [guardianPhone, setGuardianPhone] = useState("");

  const [requestOut, setRequestOut] = useState<ConsentRequestOut | null>(null);
  const [withdrawOut, setWithdrawOut] = useState<ConsentWithdrawOut | null>(
    null,
  );
  const [scopes, setScopes] = useState<ScopeState>({
    participation: false,
    public: false,
  });
  const [pendingGate, setPendingGate] = useState(true);

  const [error, setError] = useState<ApiError | null>(null);
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({});
  const [pending, setPending] = useState(false);
  const [withdrawConfirm, setWithdrawConfirm] = useState(false);

  async function onRequest(e: FormEvent) {
    e.preventDefault();
    setError(null);
    setFieldErrors({});
    setPending(true);
    try {
      const out = await requestConsent(competitorId, {
        guardianName: guardianName.trim(),
        guardianEmail: guardianEmail.trim(),
        guardianPhone: guardianPhone.trim() || null,
      });
      setRequestOut(out);
      setPendingGate(
        out.status === "CONSENT_PENDING" || out.status === "PENDING",
      );
      setScopes({ participation: false, public: false });
      setWithdrawOut(null);
    } catch (err) {
      if (err instanceof ApiError) {
        setError(err);
        setFieldErrors(fieldErrorMap(err.fields));
      } else {
        setError(
          new ApiError(0, {
            error: {
              code: "HTTP_ERROR",
              message: "Could not request consent",
              fields: [],
              traceId: "",
            },
          }),
        );
      }
    } finally {
      setPending(false);
    }
  }

  async function onWithdraw() {
    if (!withdrawConfirm) {
      setWithdrawConfirm(true);
      return;
    }
    setError(null);
    setPending(true);
    try {
      const out = await withdrawConsent(competitorId);
      setWithdrawOut(out);
      setScopes({ participation: false, public: false });
      setPendingGate(true);
      setWithdrawConfirm(false);
    } catch (err) {
      if (err instanceof ApiError) {
        setError(err);
        setFieldErrors(fieldErrorMap(err.fields));
      } else {
        setError(
          new ApiError(0, {
            error: {
              code: "HTTP_ERROR",
              message: "Could not withdraw consent",
              fields: [],
              traceId: "",
            },
          }),
        );
      }
    } finally {
      setPending(false);
    }
  }

  const consentLink = requestOut
    ? `/consent/${encodeURIComponent(requestOut.token)}`
    : null;

  return (
    <div className="mx-auto max-w-xl space-y-6 px-4 py-8 sm:px-6 sm:py-10">
      <Button variant="link" className="h-auto min-h-11 px-0" asChild>
        <Link href="/competitor">← Competitor portal</Link>
      </Button>

      <Card>
        <CardHeader className="px-4 sm:px-6">
          <h1 className="text-2xl font-semibold tracking-tight">
            Guardian consent
          </h1>
          <CardDescription>
            Request and manage participation and public-display consent for
            competitor {competitorId}.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-6 px-4 sm:px-6">
          {pendingGate ? (
            <Alert data-testid="consent-pending-alert" role="status">
              <AlertTitle>CONSENT_PENDING</AlertTitle>
              <AlertDescription>
                Progression past review is blocked until participation consent
                is granted. Public display stays withheld by default.
              </AlertDescription>
            </Alert>
          ) : null}

          <div
            className="flex flex-wrap gap-2"
            data-testid="consent-scope-status"
          >
            <Badge
              variant={scopes.participation ? "default" : "outline"}
              data-testid="scope-participation"
              data-granted={scopes.participation ? "true" : "false"}
            >
              Participation: {scopes.participation ? "granted" : "not granted"}
            </Badge>
            <Badge
              variant={scopes.public ? "default" : "outline"}
              data-testid="scope-public"
              data-granted={scopes.public ? "true" : "false"}
            >
              Public display: {scopes.public ? "granted" : "withheld"}
            </Badge>
          </div>

          <form
            onSubmit={onRequest}
            className="space-y-4"
            noValidate
            data-testid="consent-request-form"
          >
            <div className="space-y-2">
              <Label htmlFor="guardianName">Guardian name</Label>
              <Input
                id="guardianName"
                className="min-h-11"
                required
                value={guardianName}
                disabled={pending}
                aria-invalid={Boolean(fieldErrors.guardianName)}
                aria-describedby={
                  fieldErrors.guardianName ? "guardianName-error" : undefined
                }
                onChange={(e) => setGuardianName(e.target.value)}
              />
              <FieldMessage
                id="guardianName-error"
                message={fieldErrors.guardianName}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="guardianEmail">Guardian email</Label>
              <Input
                id="guardianEmail"
                type="email"
                className="min-h-11"
                required
                value={guardianEmail}
                disabled={pending}
                aria-invalid={Boolean(fieldErrors.guardianEmail)}
                aria-describedby={
                  fieldErrors.guardianEmail ? "guardianEmail-error" : undefined
                }
                onChange={(e) => setGuardianEmail(e.target.value)}
              />
              <FieldMessage
                id="guardianEmail-error"
                message={fieldErrors.guardianEmail}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="guardianPhone">Guardian phone (optional)</Label>
              <Input
                id="guardianPhone"
                type="tel"
                className="min-h-11"
                value={guardianPhone}
                disabled={pending}
                onChange={(e) => setGuardianPhone(e.target.value)}
              />
            </div>
            <Button
              type="submit"
              className="min-h-11 w-full"
              disabled={pending}
              data-testid="consent-request-submit"
            >
              {pending ? "Requesting…" : "Request consent"}
            </Button>
          </form>

          {requestOut ? (
            <div
              className="space-y-2 rounded-md border border-border p-4"
              data-testid="consent-request-result"
            >
              <p className="text-sm font-medium">
                Consent request status:{" "}
                <span data-testid="consent-request-status">
                  {requestOut.status}
                </span>
              </p>
              <p className="text-xs text-muted-foreground">
                Expires {requestOut.expiresAt}
              </p>
              {consentLink ? (
                <p className="text-sm">
                  Guardian link:{" "}
                  <Link
                    href={consentLink}
                    className="font-medium underline underline-offset-2"
                    data-testid="consent-token-link"
                  >
                    {consentLink}
                  </Link>
                </p>
              ) : null}
            </div>
          ) : null}

          <div className="space-y-3 border-t border-border pt-4">
            <h2 className="text-lg font-medium">Withdraw consent</h2>
            <p className="text-sm text-muted-foreground">
              Withdrawal removes public display immediately and flags the
              record.
            </p>
            {withdrawConfirm ? (
              <Alert variant="destructive" role="alert">
                <AlertTitle>Confirm withdrawal</AlertTitle>
                <AlertDescription>
                  This withdraws participation and public-display consent.
                </AlertDescription>
              </Alert>
            ) : null}
            <Button
              type="button"
              variant={withdrawConfirm ? "destructive" : "outline"}
              className="min-h-11 w-full"
              disabled={pending}
              onClick={() => void onWithdraw()}
              data-testid="consent-withdraw"
            >
              {withdrawConfirm
                ? "Confirm withdraw consent"
                : "Withdraw consent"}
            </Button>
            {withdrawConfirm ? (
              <Button
                type="button"
                variant="ghost"
                className="min-h-11 w-full"
                onClick={() => setWithdrawConfirm(false)}
              >
                Cancel
              </Button>
            ) : null}
          </div>

          {withdrawOut ? (
            <Alert data-testid="consent-withdraw-result" role="status">
              <AlertTitle>Consent withdrawn</AlertTitle>
              <AlertDescription>
                Status: {withdrawOut.status}. Public display is removed
                {withdrawOut.publicProfileVisible ? "" : " (not visible)"}.
                {withdrawOut.flags.length > 0
                  ? ` Flags: ${withdrawOut.flags.join(", ")}.`
                  : ""}
              </AlertDescription>
            </Alert>
          ) : null}

          <ApiErrorAlert error={error} title="Consent action failed" />
        </CardContent>
      </Card>
    </div>
  );
}
